from textual.app import ComposeResult, App
from textual.containers import Container
from textual.widgets import Button, Label
from textual.message import Message


class ChildWidget(Container):
    """A widget that sends custom messages to its parent."""

    class ButtonPressed(Message):
        """Custom message sent when button is pressed."""

        def __init__(self, button_id: str) -> None:
            super().__init__()
            self.button_id = button_id

    def compose(self) -> ComposeResult:
        yield Button("Click me!", id="btn1")
        yield Button("Click me too!", id="btn2")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Send custom message to parent when button is pressed."""
        self.post_message(self.ButtonPressed(event.button.id))


class MyApp(App):
    """Main application."""

    def compose(self) -> ComposeResult:
        yield Label("Press the buttons:", id="status")
        yield ChildWidget()

    def on_child_widget_button_pressed(self, message: ChildWidget.ButtonPressed) -> None:
        """Handle custom message from ChildWidget."""
        label = self.query_one("#status", Label)
        label.update(f"Button '{message.button_id}' was pressed!")


if __name__ == "__main__":
    MyApp().run()

